mapper.update:
UPDATE user_room
SET read_seq    = #{readSeq},
    update_time = NOW()
WHERE room_id = #{roomId}
  AND user_id = #{userId}
  AND read_seq < #{readSeq}

UPDATE user_room
SET hidden_at   = NOW(),
    update_time = NOW()
WHERE room_id = #{roomId}
  AND user_id = #{userId}

UPDATE user_room
SET hidden_at   = NULL,
    update_time = NOW()
WHERE room_id = #{roomId}
  AND user_id = #{userId}
  AND hidden_at IS NOT NULL

