SELECT 
FROM message m
WHERE m.room_id = #{roomId} AND m.seq = #{seq}

SELECT 
FROM message m
WHERE m.room_id = #{roomId} AND m.client_msg_id = #{clientMsgId}

SELECT 
FROM message m
WHERE m.msg_id = #{messageId}

SELECT 
FROM message m
WHERE m.room_id = #{roomId}

  AND m.seq < #{beforeSeq}

ORDER BY m.seq DESC
LIMIT #{limit}

SELECT t.msg_id AS msgId, t.delivery_seq AS deliverySeq
FROM timeline t
WHERE t.user_id = #{userId}
  AND t.delivery_seq > #{afterDeliverySeq}
ORDER BY t.delivery_seq ASC
LIMIT #{limit}

SELECT seq
FROM user_seq
WHERE user_id = #{userId}
